"""Backtest summary shipped with the product (generated by backtest/make_report.py)."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import Any

_PATH = Path(__file__).with_name("validation.json")


@lru_cache(maxsize=1)
def load_validation() -> dict[str, Any] | None:
    """Return the validation summary, or None if no backtest has been run."""
    try:
        with _PATH.open(encoding="utf-8") as fh:
            data: dict[str, Any] = json.load(fh)
    except FileNotFoundError:
        return None
    return data
